#!/usr/bin/env python3
"""One-off repair: restore the 5 curated gene summaries that were truncated
mid-sentence when a curation batch was imported into the server overrides.

Only the `summary` field is replaced (merged), with the complete curator text
recovered from the source curation-results file; all other override fields
(curator, dates, GO, phenotypes) are preserved.

Run ON THE SERVER, from the web root, then restart the service:
    python3 scripts/fix_truncated_curation.py
    sudo systemctl restart dicty
Add --dry to preview without writing.
"""
import json, os, sys, pathlib

ROOT = pathlib.Path(__file__).resolve().parents[1]
# Resolve the same override path serve.py uses.
CANDS = [ROOT/"uploads"/"curator_state", ROOT/"uploads"/"submissions"/"curator_state",
         ROOT/"uploads"/"curations"/"curator_state", ROOT/"uploads"/"files"/"curator_state",
         ROOT/"assets"]
OVR = next((c/"curation_overrides.json" for c in CANDS if (c/"curation_overrides.json").exists()), CANDS[0]/"curation_overrides.json")

FIXED = {
 "DDB_G0275299": "''Dictyostelium'' ''cln5'' is the ortholog of human CLN5, mutations in which cause neuronal ceroid lipofuscinosis (NCL), also referred to as Batten disease. ''cln5'' is expressed during growth with expression increasing during early development and reaching peak levels at 4 hours after starvation. From 4 to 8 hours, ''cln5'' expression decreases sharply and then remains constant during the remainder of development. Cln5 has glycoside hydrolase activity and localizes to the endoplasmic reticulum, punctate regions in the cytoplasm, and the cell cortex. Numerous potential Cln5 interacting proteins were identified by LC-MS-MS, including: NagA ([/gene/DDB_G0287033 nagA]), Tpp1 ([/gene/DDB_G0269914 tpp1]) and CtsD ([/gene/DDB_G0279411 ctsD]) [http://www.ncbi.nlm.nih.gov/pubmed/29128403  (Huber et al. 2017)]. Glycosylated Cln5 is secreted during early development, with secretion occurring via an unconventional pathway linked to autophagy. Cln5 secretion is increased in ''cln3'' ([/gene/DDB_G0291157 cln3]) and ''mfsd8'' (''cln7'') ([/gene/DDB_G0272192 mfsd8]) null mutants. ''cln5'' null mutants have decreased cell-cell and cell-substrate adhesion as well as decreased chemotaxis to cAMP [http://www.ncbi.nlm.nih.gov/pubmed/30048658  (Huber et al. 2018)], [http://www.ncbi.nlm.nih.gov/pubmed/32087303  (Huber et al. 2020)]. ''cln5'' null mutants display numerous defects during growth, including decreased proliferation, aberrant cytokinesis and decreased chemotaxis to folate. In addition, growth-phase ''cln5'' null cells display an increased number of autophagosomes, increased autophagic flux, and an increased number of ubiquitinated proteins. Development-stage ''cln5'' null cell defects include delayed aggregation, precocious late-stage development, aberrant spore morphology and decreased spore germination. Several of these growth and developmental defects are associated with aberrant autophagy, supporting evidence in other systems linking NCL to the autophagy pathway. (McLaren, et al 2021, PMID: 34291044).Gene has been comprehensively annotated, 03-AUG-2021 RD Modelling five human CLN5 disease-causing mutations in Dictyostelium Cln5 shows that the protein is required for normal endo-lysosomal trafficking, 20S proteasome-mediated protein degradation, and the amount, activity, and secretion of lysosomal enzymes, and that its secretion via its signal peptide is required for timely aggregation.",
 "DDB_G0277869": "''rac1A'' encodes a guanine nucleotide-binding protein (G protein) of the Rho family of small GTPases. G proteins are key components of signal transduction networks in which they function as molecular signaling switches, binding to GDP in the off state while binding GTP in the on state. Guanine nucleotide-exchange factors (GEFs) promote the exchange of GDP for GTP on Ras GTPases thus activating them, while GTPase-activating proteins (GAPs) inactivate Ras GTPases by binding to them and promoting their intrinsic GTPase activity to hydrolyze bound GTP to GDP. RacGEFs for Rac1A include ''docD'' ([/gene/DDB_G0284725 docD]) ([http://www.ncbi.nlm.nih.gov/pubmed/19037099 Para et al. 2009]), zizB ([/gene/DDB_G0293084 zizB]), ([http://www.ncbi.nlm.nih.gov/pubmed/22366457 Pakes et al. 2012]), ''gflB'' ([/gene/DDB_G0286773 gflB]) ([http://www.ncbi.nlm.nih.gov/pubmed/27009206 Senoo et al. 2016]), Myosin M ([/gene/DDB_G0292262 myoM]) ([http://www.ncbi.nlm.nih.gov/pubmed/11208126 Geissler et al. 2000]) and possibly gxcDD ([/gene/DDB_G0279733 gxcDD]) ([http://www.ncbi.nlm.nih.gov/pubmed/17584488 Mondal et al. 2007]). DRG ([/gene/DDB_G0291978 xacA]) contains both GAP and GEF domains and displays GEF activity and weak GAP activity for Rac1A ([http://www.ncbi.nlm.nih.gov/pubmed/11285226 Manstein et al. 2001]), ([http://www.ncbi.nlm.nih.gov/pubmed/9188459 Ludbrook et al. 1997]). Although the IQGAP-related protein DGAP1 ([/gene/DDB_G0287585 rgaA]) binds to Rac1A, it does not affect its GTPase activity ([http://www.ncbi.nlm.nih.gov/pubmed/9739079 Faix et al. 1998]), ([http://www.ncbi.nlm.nih.gov/pubmed/10825297 Dumontier et al. 2000]). Filamin ([/gene/DDB_G0269100 abpC]) and activated Rac1A associate with the rasGAP GAPA ([/gene/DDB_G0269140 gapA]) to regulate actin re-modelling. ([http://www.ncbi.nlm.nih.gov/pubmed/21085675 Mondal et al. 2010]). <br />Rac1A has multiple binding partners that may function as downstream effectors. These include: the protein kinase PakA ([/gene/DDB_G0269166 pakA]) ([http://www.ncbi.nlm.nih.gov/pubmed/12952073 Mueller-Taubenberger et al. 2002]), PakC ([/gene/DDB_G0267450 pakC]) ([http://www.ncbi.nlm.nih.gov/pubmed/15470506 Park et al. 2004]), Lissencephaly-related protein LIS1 ([/gene/DDB_G0288375 lis1]) ([http://www.ncbi.nlm.nih.gov/pubmed/15800059 Rehberg et al. 2005]), diaphanous-related formin H ([/gene/DDB_G0285589 forH]) ([http://www.ncbi.nlm.nih.gov/pubmed/15908944 Schirenbeck et al. 2005]), the myosin heavy chain kinase PakB ''pakB'' ([/gene/DDB_G0276459 pakB]) ([http://www.ncbi.nlm.nih.gov/pubmed/15509655 de la Roche et al. 2005]), coronin A ([/gene/DDB_G0267382 corA]) ([http://www.ncbi.nlm.nih.gov/pubmed/24347642 Swaminathan et al. 2013]) and WASP ([/gene/DDB_G0293834 wasA]) [http://www.ncbi.nlm.nih.gov/pubmed/31786060  (Amato et al. 2019)]. Rac1A also binds to the Rho GDP-dissociation inhibitor 1 RhoGDI1 ([/gene/DDB_G0291077 rdiA]) ([http://www.ncbi.nlm.nih.gov/pubmed/12163018 Imai et al. 2002]).<br />''rac1A'' is highly similar to two additional ''Dictyostelium'' rho GTPases: ''rac1B'' ([/gene/DDB_G0268622 rac1B]) and ''rac1C'' ([/gene/DDB_G0282365 rac1C]). Expression of the three ''rac1'' genes is low during growth but increases 3-fold during aggregation before again declining to growth-stage levels during the slug stage ([http://www.ncbi.nlm.nih.gov/pubmed/8294042 Bush et al. 1993]). Expression levels for ''rac1A'' are 2.5 fold higher than for either ''rac1B'' or ''rac1C''. Overexpression of ''rac1'' genes results in increased filopodium formation, while constitutively active Rac1A and Rac1C mutants are severely impaired in growth, motility and endocytosis. In addition, these mutants were delayed in development and displayed defects in cytokinesis and F-actin organization ([http://www.ncbi.nlm.nih.gov/pubmed/10825297 Dumontier et al. 2000]). These results indicate that the Rac1 GTPases mediate processes such as cell motility, endocytosis and cytokinesis in ''Dictyostelium'' that depend on the reorganization of the actin cytoskeleton. Activated Rac1A recruits either DGAP1 or GAPA into a protein complex with cortexillin I ([/gene/DDB_G0289483 ctxA]) and cortexillin II ([/gene/DDB_G0276893 ctxB]). Assembly of this complex is necessary for the recruitment of cortexillin to the midzone of a dividing cell and for the formation of a cleavage furrow during cytokinesis ([http://www.ncbi.nlm.nih.gov/pubmed/11447112 Faix et al. 2001]). cAMP stimulation activates ''rac1A'' and it then plays a role in signaling networks that lead to both protrusion at the front and retraction at the back of ''Dictyostelium'' cells. One population of activated Rac1A accumulates at the leading edge while a distinct population accumulates at the rear. At the leading edge of migrating cells activated Rac1A participates in Scar/WAVE ([/gene/DDB_G0285253 scrA])-mediated actin polymerization and pseudopod extension. At the trailing edge activated Rac1A forms a complex with DGAP1 and the actin-binding proteins cortexillin I and cortexillin II enabling proper cell retraction ([http://www.ncbi.nlm.nih.gov/pubmed/22302991 Filic et al. 2012]), ([http://www.ncbi.nlm.nih.gov/pubmed/22891261 Veltman et al. 2012]), ([http://www.ncbi.nlm.nih.gov/pubmed/23503127 Faix et al. 2013]), ([http://www.ncbi.nlm.nih.gov/pubmed/26940518 Rivero et al. 2016]). Activated Rac1A and RacC ([/gene/DDB_G0293526 racC]) both regulate, and are regulated by, WASP. WASP interacts with activated Rac genes via its CRIB motif, and this interaction is required for WASP to generate pseudopods in the absence of SCAR/WAVE. However, this interaction also provides a means for WASP to remove activated Racs from the membrane via endocytosis. Thus, WASP contributes to front-rear cell polarity by controlling localization and cellular levels of activated Rac. [http://www.ncbi.nlm.nih.gov/pubmed/31786060  (Amato et al. 2019)].Gene has been comprehensively annotated, 08-APR-2020 RD Rac1A binds IqgD directly, and active Rac1A localises to the F-actin rings that form around surface-attached particles at the ventral cell surface; rac1A-null cells grow very poorly on bacterial lawns and have a severe cell-substrate adhesion defect while phagocytosing suspended bacteria and yeast particles normally.",
 "DDB_G0275731": "Basic annotations have been added to this gene, 16-DEC-2013 RD IqgD is an IQGAP-related scaffold that binds F-actin directly through its N-terminal calponin homology domain and binds active Rac1 GTPases and cortexillin I and II through its GRD and CT domains in a mutually exclusive manner, and it localises to the cell cortex, to macropinocytic and phagocytic cups, and to ventral F-actin rings that form around surface-bound particles. Cells lacking IqgD show normal axenic growth, macropinocytosis and uptake of suspended bacteria, but form markedly smaller plaques on bacterial lawns, adhere poorly to the substrate, and ingest yeast particles and surface-immobilised 1 micron beads far less efficiently than wild type.",
 "DDB_G0276893": "Basic annotations have been added to this gene, 09-JAN-2013 PF Cortexillin II co-immunoprecipitates with and directly binds IqgD, and although ctxB-null cells grow normally on bacterial lawns they are significantly impaired in phagocytosis of surface-attached microbeads.",
 "DDB_G0289483": "Basic annotations have been added to this gene, 09-JAN-2013 PF; annotation contributions: PMID 22902739 Daniel Dickinson. Cortexillin I co-immunoprecipitates with endogenous IqgD and binds it directly in a BiFC assay, and ctxA-null cells phenocopy iqgD-null cells in showing markedly reduced growth on bacterial lawns together with reduced uptake of surface-attached microbeads."
}

def main():
    dry = "--dry" in sys.argv
    ov = json.loads(OVR.read_text()) if OVR.exists() else {}
    changed = 0
    for ddb, summary in FIXED.items():
        cur = ov.get(ddb, {})
        old = (cur.get("summary") or "")
        if old.strip() == summary.strip():
            print(f"  {ddb}: already correct")
            continue
        print(f"  {ddb}: {len(old)} -> {len(summary)} chars; tail now ...{summary[-60:]!r}")
        cur["summary"] = summary
        ov[ddb] = cur
        changed += 1
    print(f"\n{changed} summaries to fix; overrides file: {OVR}")
    if dry:
        print("DRY RUN - nothing written"); return
    tmp = OVR.with_suffix(".json.tmp")
    tmp.write_text(json.dumps(ov, ensure_ascii=False, indent=1))
    os.replace(tmp, OVR)
    print("written. Now: sudo systemctl restart dicty")

if __name__ == "__main__":
    main()
